"use client";

import { useMemo, useState } from "react";
import { useTranslations } from "next-intl";
import { Check, Loader2, Search, Sparkles } from "lucide-react";
import { createPlantAction } from "@/lib/actions";
import PlantIllustration from "@/components/PlantIllustration";
import PlantQuestions, { Label } from "@/components/PlantQuestions";
import type { SpeciesSummary } from "@/lib/species";

/**
 * Species search → questions → save. Also the "which one is it?" fallback
 * linked from AddPlantFlow. A name not in the library can be generated by
 * Claude via /api/care-profile (which reuses an existing species when the
 * name is a synonym — L30).
 */
export default function ManualAddForm({ species }: { species: SpeciesSummary[] }) {
  const t = useTranslations("manualAdd");
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState<SpeciesSummary | null>(null);
  const [generating, setGenerating] = useState(false);
  const [generateError, setGenerateError] = useState<string | null>(null);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return species;
    return species.filter((s) => s.common_name.toLowerCase().includes(q) || s.scientific_name.toLowerCase().includes(q));
  }, [query, species]);

  async function generateForQuery() {
    const name = query.trim().slice(0, 80);
    if (!name) return;
    setGenerating(true);
    setGenerateError(null);
    try {
      const res = await fetch("/api/care-profile", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ common_name: name }),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok || !data) throw new Error();
      setSelected(data as SpeciesSummary);
    } catch {
      setGenerateError(t("generateError"));
    } finally {
      setGenerating(false);
    }
  }

  return (
    <form action={createPlantAction} className="space-y-6">
      <section>
        <Label htmlFor="species-search">{t("whatKind")}</Label>
        <div className="relative mt-2">
          <Search className="pointer-events-none absolute top-1/2 left-4 size-4 -translate-y-1/2 text-faint" strokeWidth={2.2} />
          <input
            id="species-search"
            type="search"
            value={query}
            maxLength={80}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={t("searchPlaceholder")}
            className="w-full rounded-full border border-line bg-surface py-3 pr-4 pl-10 text-base outline-none ring-forest-500 placeholder:text-faint focus:ring-2"
          />
        </div>

        <div className="mt-3 max-h-72 space-y-1.5 overflow-y-auto rounded-3xl border border-line bg-surface p-2 shadow-soft">
          {filtered.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-muted">{t("noMatches")}</p>
          ) : (
            filtered.map((s) => {
              const active = selected?.id === s.id;
              return (
                <button
                  key={s.id}
                  type="button"
                  onClick={() => setSelected(s)}
                  aria-pressed={active}
                  className={`flex w-full items-center gap-3 rounded-2xl px-3 py-2.5 text-left outline-none transition-colors focus-visible:ring-2 focus-visible:ring-forest-500 ${
                    active ? "bg-sprout-100 ring-1 ring-forest-500" : "hover:bg-surface-sunken"
                  }`}
                >
                  <PlantIllustration illustrationKey={s.illustration_key} size={40} />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-bold text-ink">{s.common_name}</span>
                    <span className="block truncate text-xs text-muted italic">{s.scientific_name}</span>
                  </span>
                  {active ? <Check className="size-5 shrink-0 text-forest-700" strokeWidth={2.4} /> : null}
                </button>
              );
            })
          )}
        </div>

        {query.trim() && !selected ? (
          <div className="mt-3">
            <button
              type="button"
              onClick={generateForQuery}
              disabled={generating}
              className="flex w-full items-center justify-center gap-2 rounded-full border border-dashed border-sprout-300 bg-sprout-100/60 px-4 py-3 text-sm font-semibold text-forest-700 transition-colors hover:bg-sprout-100 disabled:opacity-60"
            >
              {generating ? (
                <>
                  <Loader2 className="size-4 animate-spin" strokeWidth={2.4} />
                  {t("generating", { name: query.trim() })}
                </>
              ) : (
                <>
                  <Sparkles className="size-4" strokeWidth={2.4} />
                  {t("generate", { name: query.trim() })}
                </>
              )}
            </button>
            {generateError ? (
              <p role="alert" className="mt-2 text-center text-xs font-medium text-bloom-600">
                {generateError}
              </p>
            ) : null}
          </div>
        ) : null}
      </section>

      {selected ? <PlantQuestions key={selected.id} species={selected} /> : null}
    </form>
  );
}
